/**
 * The rules behind stand-in schedules, with no database in them.
 *
 * <p><b>Why this exists.</b> The gate lets a person in when they have a
 * workday on today's schedule, and today's schedule comes from Oracle. Since
 * 2026-10-02 Oracle has been writing day D on the morning of D rather than the
 * evening before, and on some mornings not before the first shift: on 10-07
 * Georgia's gate refused people from 05:45 until the day was generated by hand
 * at 06:07, and on 10-09 it landed at 06:45, after 67 people across NJ299,
 * NJ5903 and Georgia had been refused.
 *
 * <p>So when a building has nothing from Oracle for today by
 * {@link STAND_IN_FROM_HOUR} in its own zone, CloudTime writes a stand-in: one
 * workday for everybody that building scheduled on any of the last
 * {@link LOOKBACK_DAYS} days. Measured over 09-24 to 10-08 at NJ299, NJ5903,
 * Georgia and California, that would have admitted all but 11 of 7,172
 * scheduled arrivals; last week's same day alone would have missed 304, and
 * yesterday alone 474. On 10-09 it covers every one of the 67 refused.
 *
 * <p><b>What happens when Oracle arrives.</b> The schedule pull already
 * replaces a stand-in row with Oracle's, because a stand-in carries no Oracle
 * fingerprint and so reads as a change (schedule-sync.service.ts). That is the
 * confirmation. Once Oracle has sent the building's day, the stand-in rows
 * still standing are people Oracle did not schedule, and they are removed. A
 * person removed while inside can still leave: the gate admits anybody whose
 * last gate scan is IN.
 */

/** How far back a person counts as someone this building schedules. */
export const LOOKBACK_DAYS = 7;

/**
 * Hour in the building's own zone from which a missing day is stood in for.
 * On the mornings Oracle's day came on its own in time (10-06, 10-08) it
 * landed between 01:40 and 03:15, and the first arrival at any building is
 * Georgia's, around 05:00.
 */
export const STAND_IN_FROM_HOUR = 4;

/**
 * Share of the building's usual people Oracle must have sent before its day
 * counts as arrived. Oracle writes a day in one go, so a real arrival is far
 * above this; a partial one (2 rows for NJ, 2026-09-25) is far below it.
 */
export const ARRIVED_SHARE = 0.5;

/** A building's date and hour in its own zone. */
export function siteClock(now: Date, timezone: string): { today: string; hour: number } {
  const today = new Intl.DateTimeFormat("en-CA", { timeZone: timezone }).format(now);
  const hour = Number(
    new Intl.DateTimeFormat("en-US", { timeZone: timezone, hour: "2-digit", hourCycle: "h23" }).format(now),
  );
  return { today, hour };
}

/** A YYYY-MM-DD date moved by whole days. */
export function addDays(iso: string, days: number): string {
  const d = new Date(`${iso}T00:00:00.000Z`);
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

/**
 * Whether Oracle has sent this building's day.
 *
 * @param oracleRows today's rows here that Oracle has sent at least once
 * @param usualPeople people this building scheduled in the last LOOKBACK_DAYS
 */
export function oracleArrived(oracleRows: number, usualPeople: number): boolean {
  if (oracleRows <= 0) return false;
  return usualPeople <= 0 || oracleRows >= usualPeople * ARRIVED_SHARE;
}

export type StandInStep =
  /** Nothing to do. */
  | "NONE"
  /** Oracle has not sent the day, but it is too early to stand in for it. */
  | "WAIT"
  /** Oracle has not sent the day: give everybody usual a workday. */
  | "STAND_IN"
  /** Oracle has sent the day: remove the stand-ins it did not confirm. */
  | "REMOVE_EXTRAS";

export function planStandIn(input: {
  hour: number;
  oracleRows: number;
  usualPeople: number;
  standInRows: number;
  /** False turns off writing stand-ins. Removing them is never turned off. */
  enabled: boolean;
}): StandInStep {
  if (oracleArrived(input.oracleRows, input.usualPeople)) {
    return input.standInRows > 0 ? "REMOVE_EXTRAS" : "NONE";
  }
  if (!input.enabled || input.usualPeople <= 0) return "NONE";
  return input.hour >= STAND_IN_FROM_HOUR ? "STAND_IN" : "WAIT";
}

/** One recent workday, as read from schedule_days. */
export type RecentDay = {
  employeeId: string;
  workDate: string;
  shiftId: string | null;
  startTime: string | null;
  endTime: string | null;
  mealMinutes: number | null;
};

export type StandInDay = Omit<RecentDay, "workDate">;

/**
 * One stand-in per usual person who has no row today, carrying the times of
 * their latest recent workday, which is what Oracle most often sends again.
 * A person with any row today is left alone, including one Oracle sent as not
 * a workday and one a person added by hand.
 */
export function pickStandIns(recent: RecentDay[], hasRowToday: Set<string>): StandInDay[] {
  const latest = new Map<string, RecentDay>();
  for (const day of recent) {
    if (hasRowToday.has(day.employeeId)) continue;
    const seen = latest.get(day.employeeId);
    if (!seen || day.workDate > seen.workDate) latest.set(day.employeeId, day);
  }
  return [...latest.values()].map((day) => ({
    employeeId: day.employeeId,
    shiftId: day.shiftId,
    startTime: day.startTime,
    endTime: day.endTime,
    mealMinutes: day.mealMinutes,
  }));
}
